from analyze_archive import *
import numpy as np

# Work entirely in integer 0.0001 score units.  Each day is an integer box
# intersected with one exact total.  Configuration coefficients are scaled
# to integers by the LCM of the two launched-run counts.
def setup(q):
 f=tuple(q['from'][k] for k in KNOBS);t=tuple(q['to'][k] for k in KNOBS)
 nf=len(groups[f]);nt=len(groups[t]);assert nf and nt
 mult=math.lcm(nf,nt)
 weights={r: (mult//nt if config[r]==t else 0)-(mult//nf if config[r]==f else 0) for r in launch}
 return weights,10000*mult

def allocate(cap_by_weight,total,maximize):
 assert 0<=total<=sum(cap_by_weight.values()),(total,cap_by_weight)
 value=0
 for w,cap in sorted(cap_by_weight.items(),reverse=maximize):
  z=min(total,cap);value+=w*z;total-=z
 assert total==0
 return value

def day_extrema(rr,T,weights):
 caps=collections.defaultdict(int);base=0;B=T
 for r in rr:
  l,u=bounds[r];w=weights[r];base+=w*l;B-=l;caps[w]+=u-l
 return base+allocate(caps,B,False),base+allocate(caps,B,True)

def sharp(q):
 weights,denom=setup(q);lo=hi=0;details={}
 for d,rr in sorted(days.items()):
  a,b=day_extrema(rr,digest[d][1],weights);lo+=a;hi+=b
  if a!=b:details[d]=(Fraction(a,denom),Fraction(b,denom))
 return Fraction(lo,denom),Fraction(hi,denom),details

def day_guarantee(rr,T,weights,S,brute=False):
 caps=collections.defaultdict(int);C_S=0;B=T
 for r in rr:
  l,u=bounds[r];c=u-l;B-=l
  if r in S:C_S+=c
  else:caps[weights[r]]+=c
 C_R=sum(caps.values())
 a=max(0,B-C_S);b=min(C_R,B);assert a<=b
 # Shared recovered values allow the remaining (lower-shifted) sum t to be
 # ANY integer in [a,b]. Given t, the recovered objective cancels, and the
 # width is max objective minus min objective for the remaining variables.
 # This is piecewise linear in t, with integer capacity-sum breakpoints.
