  # Independent exhaustive integer-t verification using discrete marginal
  # arrays, rather than the capacity-breakpoint optimization.
  ascending=np.concatenate([np.full(c,w,dtype=np.int64) for w,c in sorted(caps.items())]) if C_R else np.array([],dtype=np.int64)
